urls=['https://nubs.nju.edu.cn/de/aa/c8896a843434/page.htm','https://yjsy.uibe.edu.cn/cms/infoArticleList.do?columnId=2398','https://sem.bjtu.edu.cn/show-357-10491.html','https://bus.sysu.edu.cn/article/12430','https://yzb.zuel.edu.cn/']
